-- 039 AI 관련 면접 질문 (클론 ZAVAPASS-clone 전용) — 2026-11-18
-- ① 질문 36개를 qb_additions에 ADD-9001~9036으로 넣음 (company_key 'AI00', job = 묶음, job_detail = 유형)
--    → 꼬리질문·채점이 지금처럼 질문 의도·평가 포인트·예상 꼬리질문을 읽어 씀 (additionInfo, 번호 형식 ADD-0000)
-- ② 추가 질문 다시 넣기(qb_additions_import)를 해도 AI 질문은 지워지지 않게 함
-- ③ 학생 화면이 질문 문장만 받아 가는 함수 list_ai_questions (의도·평가 포인트는 내려보내지 않음)
-- ④ 관리자 스위치 app_settings.ai_topic (기본 켜짐)
delete from public.qb_additions where company_key = 'AI00';


create or replace function public.list_ai_questions()
 returns table(id text, grp text, kind text, qtype text, question text)
 language sql stable security definer set search_path to 'public'
as $fn$
  select a.id, a.job, a.job_detail, a.qtype, a.question
    from public.qb_additions a
   where auth.uid() is not null and a.company_key = 'AI00' and a.active
     and coalesce((select (s.value->>'enabled')::boolean from public.app_settings s where s.key = 'ai_topic'), true)
   order by a.id;
$fn$;
revoke all on function public.list_ai_questions() from public, anon;
grant execute on function public.list_ai_questions() to authenticated;

create or replace function public.qb_additions_import(p_companies jsonb, p_rows jsonb, p_token text default null::text)
 returns jsonb language plpgsql security definer set search_path to 'public'
as $function$
declare res jsonb;
begin
  if not public.qb_can_import(p_token) then raise exception '관리자만 할 수 있어요' using errcode = '42501'; end if;
  delete from public.qb_additions where id !~ '^HLR-' and company_key <> 'AI00';   -- 039: AI 관련 질문(AI00)은 다시 넣기에서 지우지 않음
  select x->>'key', x->>'name', x->>'grp', nullif(x->>'priority','')::int, nullif(x->>'talent_id',''), x->>'note'
    from jsonb_array_elements(coalesce(p_companies, '[]'::jsonb)) x
  on conflict (key) do update set name = excluded.name, grp = excluded.grp, priority = excluded.priority, talent_id = coalesce(excluded.talent_id, qb_addition_companies.talent_id), note = excluded.note;
                                   question, rep, has_followup, orig_type, intent, eval_points, followups, basis, orig_id, src)
  select x->>'id', x->>'company_key', x->>'company', x->>'grp', nullif(x->>'priority','')::int, x->>'job', x->>'job_detail', x->>'rank',
         nullif(x->>'year','')::int, nullif(x->>'recency',''), nullif(x->>'weight','')::numeric, nullif(x->>'difficulty',''), nullif(x->>'result',''),
         x->>'stage', x->>'qtype', x->>'question', nullif(x->>'rep',''), coalesce((x->>'has_followup')::boolean, false),
         x->>'orig_type', x->>'intent', x->>'eval_points', x->>'followups', x->>'basis', x->>'orig_id', x->>'src'
    from jsonb_array_elements(coalesce(p_rows, '[]'::jsonb)) x;
  res := public.qb_apply_additions(public.qb_active_ver());
  return res || jsonb_build_object('추가분_질문', (select count(*) from public.qb_additions), '추가분_기업', (select count(*) from public.qb_addition_companies));
end $function$;
